    (* [comment removed for export] *)
    Lemma fin_S6 : forall (Fx : bvmap 5 word) (fcx : bv 32) msF mo sx psx XS mc junk (x5 x6 x7 xa3 xa4 xa5 xa6 xa7 x28 x29 x30 x31 : word) (stt tot : Z),
      as_AKREL H sx (mkCfg msF mo) -> as_MPRES H mo0 mo -> frm0 fcx ->
      as_VIS H sx msF = MS (mkR ra sp gp tp x5 x6 x7 s0 s1 a0 (Z_to_bv 64 stt) (Z_to_bv 64 tot) xa3 xa4 xa5 xa6 xa7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 x28 x29 x30 x31)
                          Fx (wz A_SUSPEND6) fcx None mc (seg_rom asegs) ->
      cst sx psx XS mc -> psW psx junk -> stk asegs mc lo (bv_unsigned sp) ->
      p <= ps_end psx <= e -> 0 <= ps_depth psx <= 32 ->
      pv_spent H st0 (e - p) (lb_bytes (blocks_vs (ps_vs psx))) (as_AL H s) (as_AL H sx) ->
